const billingTransfers = `-- name: BillingTransfers :many
SELECT t.uuid,o.uuid AS organization_uuid,i.uuid AS invoice_uuid,i.payment_reference,t.amount_minor,t.status,t.attachment_uuid,t.note,t.created_at
FROM billing_bank_transfers t JOIN organizations o ON o.id=t.organization_id JOIN billing_invoices i ON i.organization_id=t.organization_id AND i.id=t.invoice_id
WHERE ($1::bigint=0 OR t.organization_id=$1::bigint)
ORDER BY t.id DESC LIMIT $3 OFFSET $2
`

type BillingTransfersParams struct {
	OrganizationID int64 `json:"organization_id"`
	RowOffset      int32 `json:"row_offset"`
	RowLimit       int32 `json:"row_limit"`
}

type BillingTransfersRow struct {
	Uuid             uuid.UUID          `json:"uuid"`
	OrganizationUuid uuid.UUID          `json:"organization_uuid"`
	InvoiceUuid      uuid.UUID          `json:"invoice_uuid"`
	PaymentReference string             `json:"payment_reference"`
	AmountMinor      int64              `json:"amount_minor"`
	Status           string             `json:"status"`
	AttachmentUuid   pgtype.UUID        `json:"attachment_uuid"`
	Note             string             `json:"note"`
	CreatedAt        pgtype.Timestamptz `json:"created_at"`
}

func (q *Queries) BillingTransfers(ctx context.Context, arg BillingTransfersParams) ([]BillingTransfersRow, error) {
	rows, err := q.db.Query(ctx, billingTransfers, arg.OrganizationID, arg.RowOffset, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BillingTransfersRow{}
	for rows.Next() {
		var i BillingTransfersRow
		if err := rows.Scan(
			&i.Uuid,
			&i.OrganizationUuid,
			&i.InvoiceUuid,
			&i.PaymentReference,
			&i.AmountMinor,
			&i.Status,
			&i.AttachmentUuid,
			&i.Note,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

